let expansionContentId=5000
for(const level of levels){for(const [title,words] of expansionLexicon[level]) generatedContent.push({id:expansionContentId++,section:'words',title,description:`Дополнительная тематическая коллекция ${level}: ${title}.`,status:'published',level,icon:'📚',xp:0,category:title,payload:{words}})}

function expansionQuiz(level:string,topic:string,words:any[],n:number){return Array.from({length:10},(_,j)=>{const a=words[(n+j)%words.length];const others=words.filter((x:any)=>x.ru!==a.ru);const options=[a.ru,...[1,2,3].map(k=>others[(n+j+k)%others.length]?.ru).filter(Boolean)];return {id:j+1,question:`Выбери наиболее точный перевод для “${a.en}”. · ${level}-${n+1}-${j+1}`,options,correctAnswer:a.ru,explanation:`“${a.en}” — «${a.ru}».`}})}
for(const level of levels){const cols=expansionLexicon[level];for(let i=0;i<50;i++){const [topic,words]=cols[i%cols.length];generatedContent.push({id:expansionContentId++,section:'quizzes',title:`${topic} · Дополнительный квиз ${i+1}`,description:`Дополнительный квиз ${level}: лексика и контекст по теме ${topic}.`,status:'published',level,icon:'🧠',xp:20+levels.indexOf(level)*5,category:i%2?'Словарный запас':'Контекст',payload:{questions:expansionQuiz(level,topic,words,i)}})}}
const expansionGameTypes=['word-match','word-builder','memory','speed','grammar-race','sentence-order','true-false','missing-word','translation-input','crossword','drag-sort']
for(const level of levels){const cols=expansionLexicon[level];for(let i=0;i<60;i++){const [topic,words]=cols[i%cols.length];const type=expansionGameTypes[i%expansionGameTypes.length];const chosen=Array.from({length:6},(_,j)=>words[(i*3+j)%words.length]).map((w:any,j:number)=>({...w,hint:`${level} · ${topic}`,category:topic,options:[w.en,...words.filter((z:any)=>z.en!==w.en).slice(0,3).map((z:any)=>z.en)],correctAnswer:w.en,explanation:`${w.en} — ${w.ru}.`,row:j,col:(j*2)%5,direction:j%2?'down':'across'}));generatedContent.push({id:expansionContentId++,section:'games',title:`${topic} · Дополнительная игра ${i+1}`,description:`Дополнительная интерактивная практика ${level} по теме ${topic}.`,status:'published',level,icon:'🎮',xp:20+levels.indexOf(level)*5,category:topic,payload:{gameType:type,words:chosen,puzzleSize:3,oddAnswer:chosen.at(-1)?.en||''}})}}
const expansionChallengeCats=['Словарь','Контекст','Чтение','Письмо','Говорение','Точность','Повторение','Скорость','Понимание','Мини-тест','День','Неделя','Коммуникация','Прогресс','Смешанное']
for(const level of levels){const cols=expansionLexicon[level];for(let i=0;i<40;i++){const [topic,words]=cols[i%cols.length];generatedContent.push({id:expansionContentId++,section:'challenges',title:`${level} Challenge ${i+1}: ${topic}`,description:`Дополнительный челлендж ${level}, соответствующий теме ${topic}.`,status:'published',level,icon:'⚡',xp:25+levels.indexOf(level)*5,category:expansionChallengeCats[i%expansionChallengeCats.length],payload:{goal:`Выполни 8 из 10 заданий по теме «${topic}».`,instructions:`Работай с лексикой и контекстом уровня ${level}; проверяй значение и употребление.`,reward:`+${25+levels.indexOf(level)*5} XP`,questions:expansionQuiz(level,topic,words,i)}})}}
let expansionMissionId=5000
for(const level of levels){const cols=expansionLexicon[level];for(let i=0;i<60;i++){const [topic,words]=cols[i%cols.length];const q=expansionQuiz(level,topic,words,i).slice(0,5+i%6);generatedMissions.push({id:expansionMissionId++,title:`${level} Mission Plus ${i+1}: ${topic}`,description:`Дополнительная миссия ${level}: лексика и понимание темы ${topic}.`,category:'Словарный запас',level,xp:25+levels.indexOf(level)*10,icon:'🎯',duration:`${6+i%7} мин`,status:'published',tasks:q})}}


// V7.14 content QA normalization. Keeps UI untouched; validates generated learning payloads.
const choiceTypes=new Set(['word-match','speed','grammar-race'])
for(const item of generatedContent){
 if(item.section!=='games') continue
 const type=item.payload?.gameType||'word-match'
 const words=Array.isArray(item.payload?.words)?item.payload.words:[]
 words.forEach((w:any,i:number)=>{
   if(!choiceTypes.has(type)) delete w.options
   if(type==='sentence-order') w.hint=w.example||`The word “${w.en}” means «${w.ru}».`
   if(type==='missing-word') w.hint=`The English expression for «${w.ru}» is ___.`
   if(type==='true-false') w.hint=`“${w.en}” means «${w.ru}».`
   if(type==='crossword'){w.row=i*2;w.col=0;w.direction='across'}
 })
 if(type==='drag-sort' && words.length){
   // Split the visible cards into two explicit practice groups so sorting has >1 destination.
   words.forEach((w:any,i:number)=>w.category=i<Math.ceil(words.length/2)?`${item.category} · A`:`${item.category} · B`)
 }
}

